function normalizeWord(value) {
  return value.toLocaleUpperCase('tr-TR');
}

function getInitialState(wordLength = 5, keepScores = false, previous, startingPlayer = 'player1') {
  const answers = WORDS[wordLength] || WORDS[5];
  const usedWords = new Set(
    (previous?.lingoHistory || previous?.askedWords || [])
      .map((entry) => normalizeWord(typeof entry === 'string' ? entry : entry.word || ''))
      .filter(Boolean)
  );
  const unusedAnswers = answers
    .map(normalizeWord)
    .filter((word) => !usedWords.has(word));
  const availableAnswers = unusedAnswers.length ? unusedAnswers : answers.map(normalizeWord);
  const answer = availableAnswers[Math.floor(Math.random() * availableAnswers.length)];
  const lingoHistory = keepScores && previous && Array.isArray(previous.lingoHistory)
    ? previous.lingoHistory.map((entry) => ({ ...entry }))
    : [];
  lingoHistory.push({ word: null, winner: null });
  return {
    gameId: 'lingo',
    wordLength,
    answer,
    lingoHistory,
    askedWords: lingoHistory.map((entry) => entry.word).filter(Boolean),
    guesses: [],
    currentTurn: startingPlayer,
    startingPlayer,
    turnDeadline: Date.now() + TURN_MS,
    winner: null,
    player1: keepScores && previous ? previous.player1 : null,
    player2: keepScores && previous ? previous.player2 : null,
    score1: keepScores && previous ? (previous.score1 || 0) : 0,
    score2: keepScores && previous ? (previous.score2 || 0) : 0
  };
}

function publicState(game) {
  const { answer, pausedTurnMs, ...state } = game;
  const firstLetter = [...answer][0];
  const lingoHistory = (game.lingoHistory || []).map((entry) => ({
    word: entry.winner ? entry.word : null,
    winner: entry.winner
  }));
  return { ...state, firstLetter, lingoHistory, askedWords: lingoHistory.map((entry) => entry.word).filter(Boolean), answer: game.winner ? answer : null };
}

function completeHistoryEntry(game, winner) {
  if (!Array.isArray(game.lingoHistory) || game.lingoHistory.length === 0) return;
  game.lingoHistory[game.lingoHistory.length - 1] = {
    word: game.answer,
    winner
  };
  game.askedWords = game.lingoHistory.map((entry) => entry.word).filter(Boolean);
}

function advanceTurn(game, timedOut = false, now = Date.now()) {
  if (!game || game.gameId !== 'lingo' || game.winner) return false;
  if (timedOut) game.guesses.push({ player: game.currentTurn, guess: '', feedback: [], timedOut: true });
  if (game.guesses.length >= MAX_GUESSES) {
    game.winner = 'draw';
    completeHistoryEntry(game, 'draw');
    game.turnDeadline = null;
  } else {
    game.currentTurn = game.currentTurn === 'player1' ? 'player2' : 'player1';
    game.turnDeadline = now + TURN_MS;
  }
  return true;
}

function submitGuess(game, socketId, rawGuess, now = Date.now()) {
  if (!game || game.gameId !== 'lingo' || game.winner || game.turnDeadline <= now ||
    typeof rawGuess !== 'string') return false;
  const currentPlayerId = game.currentTurn === 'player1' ? game.player1 : game.player2;
  if (currentPlayerId !== socketId) return false;

  const guess = normalizeWord(rawGuess.trim());
  if ([...guess].length !== game.wordLength || !/^[A-ZÇĞİÖŞÜ]+$/u.test(guess)) return false;
  if ([...guess][0] !== [...game.answer][0]) return false;

  const answerLetters = [...game.answer];
  const guessLetters = [...guess];
  const feedback = Array(game.wordLength).fill('absent');
  const remaining = new Map();

  answerLetters.forEach((letter, index) => {
    if (guessLetters[index] === letter) feedback[index] = 'correct';
    else remaining.set(letter, (remaining.get(letter) || 0) + 1);
  });
  guessLetters.forEach((letter, index) => {
    if (feedback[index] === 'correct') return;
    const count = remaining.get(letter) || 0;
    if (count > 0) {
      feedback[index] = 'present';
      remaining.set(letter, count - 1);
    }
  });

  game.guesses.push({ player: game.currentTurn, guess, feedback, timedOut: false });
  if (guess === game.answer) {
    game.winner = game.currentTurn;
    completeHistoryEntry(game, game.currentTurn);
    game[game.currentTurn === 'player1' ? 'score1' : 'score2'] += 1;
    game.turnDeadline = null;
  } else if (game.guesses.length >= MAX_GUESSES) {
    game.winner = 'draw';
    completeHistoryEntry(game, 'draw');
    game.turnDeadline = null;
  } else {
    game.currentTurn = game.currentTurn === 'player1' ? 'player2' : 'player1';
    game.turnDeadline = now + TURN_MS;
  }
  return true;
}

module.exports = { TURN_MS, WORDS, advanceTurn, getInitialState, normalizeWord, publicState, submitGuess };
